import java.io.*;import java.util.*;public class Main {public static void main(String[] args) throws IOException {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));PrintWriter out = new PrintWriter(System.out);int n = Integer.parseInt(br.readLine());int[] prefixSums = new int[n];StringTokenizer st = new StringTokenizer(br.readLine());int currentSum = 0;for (int i = 0; i < n; i++) {currentSum += Integer.parseInt(st.nextToken());prefixSums[i] = currentSum;}int m = Integer.parseInt(br.readLine());st = new StringTokenizer(br.readLine());for (int i = 0; i < m; i++) {int q = Integer.parseInt(st.nextToken());int index = Arrays.binarySearch(prefixSums, q);if (index < 0) {index = -(index + 1);}out.println(index + 1);}out.flush();out.close();}}